"""Generated by the QA agent for STORY-102: See my accounts and my total balance."""
import re

from playwright.sync_api import expect

from nilebank_helpers import money


def test_tc_102_01_api_lists_all_my_accounts(amira):
    """TC-102-01 (API)"""
    r = amira.get("/api/accounts")
    assert r.status_code == 200, r.text
    accounts = {a["id"]: a for a in r.json()}
    assert set(accounts) == {"CUR-1001", "SAV-1002"}
    assert accounts["CUR-1001"]["balance"] == 25000.00
    assert accounts["SAV-1002"]["balance"] == 100000.00
    assert all(a["iban"].startswith("EG") for a in accounts.values())


def test_tc_102_02_balances_formatted_as_money_ui(signed_in):
    """TC-102-02 (UI)"""
    expect(signed_in.get_by_test_id("account-balance-CUR-1001")).to_have_text("EGP 25,000.00")
    expect(signed_in.get_by_test_id("account-balance-SAV-1002")).to_have_text("EGP 100,000.00")


def test_tc_102_03_total_is_sum_of_all_accounts_ui(signed_in):
    """TC-102-03 (UI)"""
    shown = money(signed_in.get_by_test_id("total-balance").inner_text())
    cards = sum(money(signed_in.get_by_test_id(f"account-balance-{a}").inner_text()) for a in ("CUR-1001", "SAV-1002"))
    assert shown == cards == 125000.00, f"total shows {shown:,.2f}, accounts add up to {cards:,.2f}"


def test_tc_102_04_signed_out_users_are_sent_to_sign_in(bank, page):
    """TC-102-04 (API + UI)"""
    assert bank.get("/api/accounts").status_code == 401
    page.goto("/dashboard")
    expect(page).to_have_url(re.compile(r".*/login(\?.*)?$"))
